async function httpJson(url, options = {}) {
  const response = await helpers.httpRequest({
    method: options.method || 'GET',
    url,
    headers: options.headers || {},
    body: options.body,
    json: true,
    returnFullResponse: true,
    ignoreHttpStatusErrors: true,
  });
  const status = response.statusCode || response.status || 200;
  return { ok: status >= 200 && status < 300, status, body: response.body ?? response };
}
const input = $json.body ?? $json;
const headers = $json.headers ?? {};
const token = headers['x-sti-agent-token'] || headers['X-STI-Agent-Token'] || input.agentToken;
if (!$env.N8N_AGENT_TOKEN || token !== $env.N8N_AGENT_TOKEN) {
  throw new Error('Unauthorized reindex request');
}
if (!$env.GEMINI_API_KEY) {
  throw new Error('GEMINI_API_KEY is not configured');
}
const limit = Math.min(Math.max(Number(input.limit || 25), 1), 50);
const pendingResponse = await httpJson($env.STI_RAG_PENDING_URL, {
  method: 'POST',
  headers: {
    'content-type': 'application/json',
    'x-sti-agent-token': $env.N8N_AGENT_TOKEN,
  },
  body: { limit },
});
const pendingBody = pendingResponse.body;
if (!pendingResponse.ok) {
  throw new Error(pendingBody?.error || 'Unable to load pending RAG documents');
}
const documents = pendingBody.documents || [];
const embeddingModel = $env.GEMINI_EMBEDDING_MODEL || 'gemini-embedding-2';
let embedded = 0;
let failed = 0;
for (const doc of documents) {
  try {
    const embedResponse = await httpJson(`https://generativelanguage.googleapis.com/v1beta/models/${embeddingModel}:embedContent`, {
      method: 'POST',
      headers: {
        'content-type': 'application/json',
        'x-goog-api-key': $env.GEMINI_API_KEY,
      },
      body: {
        content: { parts: [{ text: String(doc.content || '').slice(0, 24000) }] },
        output_dimensionality: 768,
      },
    });
    const embedBody = embedResponse.body;
    if (!embedResponse.ok) throw new Error(embedBody?.error?.message || 'Gemini embedding failed');
    const embedding = embedBody?.embedding?.values || embedBody?.embeddings?.[0]?.values;
    const updateResponse = await httpJson($env.STI_RAG_EMBEDDING_URL, {
      method: 'POST',
      headers: {
        'content-type': 'application/json',
        'x-sti-agent-token': $env.N8N_AGENT_TOKEN,
      },
      body: { id: doc.id, embedding },
    });
    if (!updateResponse.ok) throw new Error(updateResponse.body?.error || 'Embedding update failed');
    embedded += 1;
  } catch (error) {
    failed += 1;
    await httpJson($env.STI_RAG_EMBEDDING_URL, {
      method: 'POST',
      headers: {
        'content-type': 'application/json',
        'x-sti-agent-token': $env.N8N_AGENT_TOKEN,
      },
      body: { id: doc.id, error: error.message || 'Embedding failed' },
    }).catch(() => undefined);
  }
}
return [{ json: { ok: true, requested: limit, loaded: documents.length, embedded, failed } }];
